'use client';

import React, { useState } from 'react';
import { Search } from 'lucide-react';

export function HeroSearch() {
  const [isFocused, setIsFocused] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');

  return (
    <div className="flex flex-col items-center justify-center mt-16 w-full animate-fade-in">
      <h2 className="text-3xl font-semibold text-navy-900 mb-8 text-center">
        مرحباً أحمد، كيف يمكنني مساعدتك اليوم؟
      </h2>

      <div className="w-full max-w-3xl relative">
        <div 
          className={`flex items-center bg-white rounded-2xl shadow-md border border-gray-100 transition-all duration-300 overflow-hidden ${
            isFocused ? 'ring-4 ring-blue-100 border-blue-300' : ''
          }`}
        >
          <div className="px-4 text-blue-600">
            <Search className="w-6 h-6" />
          </div>
          
          <input 
            type="text"
            className="flex-1 w-full py-4 bg-transparent outline-none text-navy-900 text-lg placeholder:text-slate-400"
            placeholder="ابحث في القوانين العمانية، المبادئ القضائية، أو مسوداتك السابقة..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            onFocus={() => setIsFocused(true)}
            onBlur={() => setIsFocused(false)}
          />
        </div>

        {/* Dropdown for search suggestions (Micro-interaction) */}
        {searchQuery.length > 0 && (
          <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-xl shadow-lg border border-gray-100 overflow-hidden z-50 animate-slide-up origin-top">
            <div className="p-2">
              <button className="w-full text-right px-4 py-3 hover:bg-slate-50 rounded-lg text-navy-900 transition-colors flex items-center gap-3">
                <Search className="w-4 h-4 text-slate-400" />
                <span>بحث عن "{searchQuery}" في المبادئ القضائية</span>
              </button>
              <button className="w-full text-right px-4 py-3 hover:bg-slate-50 rounded-lg text-navy-900 transition-colors flex items-center gap-3">
                <Search className="w-4 h-4 text-slate-400" />
                <span>بحث عن "{searchQuery}" في القوانين والتشريعات</span>
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
